package com.fde.ho2.config; import com.fde.ho2.model.*; import java.util.*; public class WorkflowConfig { private final Map<AgentType,WorkflowTask> tasks; public WorkflowConfig(Map<AgentType,WorkflowTask> t){tasks=new EnumMap<>(t);} public WorkflowTask task(AgentType t){return tasks.get(t);} public static WorkflowConfig broken(){Map<AgentType,WorkflowTask> m=new EnumMap<>(AgentType.class); m.put(AgentType.PLANNER,new WorkflowTask(AgentType.PLANNER,List.of(),"Create tasks")); m.put(AgentType.ORDER_ANALYSIS,new WorkflowTask(AgentType.ORDER_ANALYSIS,List.of(AgentType.PLANNER),"Analyze order")); m.put(AgentType.INVENTORY,new WorkflowTask(AgentType.INVENTORY,List.of(AgentType.RESPONSE),"Check inventory")); m.put(AgentType.RESPONSE,new WorkflowTask(AgentType.RESPONSE,List.of(AgentType.ORDER_ANALYSIS),"Final response")); return new WorkflowConfig(m);} }
